    protected override bool ShowWithoutActivation{get{return true;}}
    protected override void OnFormClosing(FormClosingEventArgs e){closing=true;base.OnFormClosing(e);}
    protected override void Dispose(bool disposing){if(disposing){closing=true;controller.ProgressChanged-=Progress;}base.Dispose(disposing);}
    void Progress(string text){if(Alive)status.Text=text;}
    void NotifyChanged(){if(!controller.IsStopping&&Changed!=null)Changed();}
    async Task RunUi(Func<Task> body){if(!Alive)return;if(busy){status.Text="正在执行操作，请稍候。";return;}busy=true;lastError="";foreach(var button in actions)button.Enabled=false;UseWaitCursor=true;try{await body();}catch(Exception error){lastError=error.Message;Log.Write(error.ToString());if(Alive)status.Text=error.Message;}finally{busy=false;if(Alive){foreach(var button in actions)button.Enabled=true;UseWaitCursor=false;}}}
    static void Fill(ListView list,IEnumerable<Dictionary<string,object>> records,Func<Dictionary<string,object>,string[]> columns){string selected=list.SelectedItems.Count==0?"":list.SelectedItems[0].Text;list.BeginUpdate();try{list.Items.Clear();foreach(var record in records){var texts=columns(record);var item=new ListViewItem(texts){Tag=record};list.Items.Add(item);if(item.Text==selected)item.Selected=true;}}finally{list.EndUpdate();}}
    async Task RefreshModel(){string directory=controller.Workspace();var value=Data.Map(await controller.Dispatch("repository-state",new Dictionary<string,object>(),directory));if(!Alive)return;workspace=directory;model=value;heading.Text="当前分支："+(String.IsNullOrEmpty(Data.Text(model,"current"))?"游离 HEAD":Data.Text(model,"current"));location.Text=workspace;
      Fill(branches,Data.Array(model,"branches").Select(Data.Map),row=>new string[]{(Convert.ToBoolean(row["current"])?"● ":"")+Data.Text(row,"name"),Convert.ToBoolean(row["remote"])?"远端":"本地",(Data.Text(row,"upstream")+" "+Data.Text(row,"tracking")).Trim(),Data.Text(row,"subject")});
      Fill(changes,Data.Array(model,"changes").Select(Data.Map),row=>new string[]{Data.Text(row,"path"),Data.Text(row,"status")});Fill(stashes,Data.Array(model,"stashes").Select(Data.Map),row=>new string[]{Data.Text(row,"reference"),Data.Text(row,"message"),Data.Text(row,"oid").Substring(0,7)});Fill(tags,Data.Array(model,"tags").Select(Data.Map),row=>new string[]{Data.Text(row,"name"),Data.Text(row,"oid").Substring(0,7),Data.Text(row,"message")});
      Fill(conflicts,Data.Array(model,"conflicts").Select(path=>new Dictionary<string,object>{{"path",Convert.ToString(path)}}),row=>new string[]{Data.Text(row,"path"),"选版 / 手工处理后标记解决"});conflictTab.Text="冲突 ("+conflicts.Items.Count+")";string file=controller.ActivePath();if(lockPath.Text.Length==0&&file.StartsWith(directory+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))lockPath.Text=file.Substring(directory.Length+1).Replace('\\','/');
      var manual=model.ContainsKey("manualMerge")?Data.Map(model["manualMerge"]):new Dictionary<string,object>();bool active=manual.ContainsKey("active")&&Convert.ToBoolean(manual["active"]);manualHeading.Text=active?(Data.Text(manual,"state")=="pending"?"合并已暂停 · 等待导入两边装配体":Data.Text(manual,"state")=="applied"?"人工结果已应用 · 等待完成合并":"双分支装配已导入 · 等待手工合图"):"尚未导入双分支装配";manualDetails.Text=active&&Data.Text(manual,"state")!="pending"?"A · 当前分支  "+Data.Text(manual,"ours")+"\r\nB · 合入分支  "+Data.Text(manual,"theirs")+"\r\n\r\n临时总装\r\n"+Data.Text(manual,"parent")+"\r\n\r\n结果总装的仓库路径\r\n"+Data.Text(manual,"target")+"\r\n\r\n在临时总装里删除、替换、复制组件并调整配合。需要时将子装配解散或另存为最终总装。\r\n完成后激活最终总装，点击“应用人工结果”核对全部图纸的写回路径。\r\n\r\n应用结果不会立即创建提交；剩余冲突处理完后，再点击“完成合并”。":"从“分支”页选择另一个分支，点击“人工合图合并”。\r\n\r\n如果 Git 合并已经遇到冲突，可直接点击“导入双分支装配”。\r\n\r\n每边的总装、子装配及零件均按固定提交取出，同名文件分别重命名并重连引用。\r\n合图副本位于工作副本外；保存成果时不会误提交两套临时历史文件。";
      if(!active&&Data.Text(manual,"state")=="completed"){manualHeading.Text="人工合图已完成 · "+Data.Text(manual,"commit").Substring(0,7);manualDetails.Text="合并提交\r\n"+Data.Text(manual,"commit")+"\r\n\r\n保留的两个父提交\r\nA · "+Data.Text(manual,"ours")+"\r\nB · "+Data.Text(manual,"theirs")+"\r\n\r\n结果总装\r\n"+Data.Text(manual,"target")+"\r\n\r\n可在 Git Graph 中查看分支汇合，也可推送到 NAS。";}
      manualView.Read(manual);if(conflicts.Items.Count>0&&!active)tabs.SelectedTab=conflictTab;
    }
    async Task Execute(string action,Dictionary<string,object> values){var result=Data.Map(await controller.Dispatch(action,values,controller.Workspace()));string message=Data.Text(result,"message");NotifyChanged();if(!Alive)return;await RefreshModel();if(!Alive)return;status.Text=String.IsNullOrEmpty(message)?"操作完成":message;if(action=="lock"||action=="unlock")await ReadLocks();if(action=="prepare-cad-merge"||action=="open-cad-merge"||action=="apply-cad-result")tabs.SelectedTab=manualTab;}
    async Task Create(bool tag){using(var dialog=new NewReferenceDialog(model,selectedCommit,tag)){if(dialog.ShowDialog(this)==DialogResult.OK)await Execute(tag?"create-tag":"create-branch",dialog.Values);}}
    async Task Rename(){var item=Selected(branches);string reference=Data.Text(item,"reference");if(Convert.ToBoolean(item["remote"]))throw new InvalidOperationException("远端分支请先在本地创建或切换；重命名后发布新分支，再按需删除旧远端分支。");string name=Prompt("重命名分支","新的分支名称",Data.Text(item,"name"));if(name!=null)await Execute("rename-branch",new Dictionary<string,object>{{"reference",reference},{"name",name}});}
    async Task DeleteBranch(){var item=Selected(branches);if(MessageBox.Show(this,"删除分支 "+Data.Text(item,"name")+"？\n本地未合并分支会拒绝删除；删除远端分支会影响团队。","gitpolar",MessageBoxButtons.YesNo,MessageBoxIcon.Question)==DialogResult.Yes)await Execute("delete-branch",new Dictionary<string,object>{{"reference",Data.Text(item,"reference")}});}
    async Task Merge(){string reference=Ref();if(reference=="refs/heads/"+Data.Text(model,"current"))throw new InvalidOperationException("请选择另一个需要合入的分支。");if(MessageBox.Show(this,"将 "+reference.Replace("refs/heads/","").Replace("refs/remotes/","")+" 合并到当前分支 "+Data.Text(model,"current")+"？","gitpolar",MessageBoxButtons.YesNo,MessageBoxIcon.Question)==DialogResult.Yes)await Execute("merge",new Dictionary<string,object>{{"reference",reference}});}
    Dictionary<string,object> StashValues(){var item=Selected(stashes);return new Dictionary<string,object>{{"reference",Data.Text(item,"reference")},{"oid",Data.Text(item,"oid")}};}
    async Task SaveStash(){string message=Prompt("暂存当前改动","暂存说明（不会推送到 NAS）","gitpolar 暂存 "+DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss"));if(message!=null)await Execute("stash-save",new Dictionary<string,object>{{"message",message}});}
    async Task DeleteStash(){var values=StashValues();if(MessageBox.Show(this,"删除 "+Convert.ToString(values["reference"])+"？请确认其中的改动已经恢复或不再需要。","gitpolar",MessageBoxButtons.YesNo,MessageBoxIcon.Question)==DialogResult.Yes)await Execute("stash-drop",values);}
    async Task DeleteTag(bool remote){string name=Data.Text(Selected(tags),"name");if(MessageBox.Show(this,"删除"+(remote?"远端":"本地")+"标签 "+name+"？","gitpolar",MessageBoxButtons.YesNo,MessageBoxIcon.Question)==DialogResult.Yes)await Execute("delete-tag",new Dictionary<string,object>{{"name",name},{"remote",remote}});}
    async Task ResolveConflict(string side){string file=Data.Text(Selected(conflicts),"path");if(MessageBox.Show(this,"冲突文件："+file+"\n保留"+(side=="ours"?"当前分支":"合入分支")+"版本？","gitpolar",MessageBoxButtons.YesNo,MessageBoxIcon.Question)==DialogResult.Yes)await Execute("resolve-conflict",new Dictionary<string,object>{{"path",file},{"side",side}});}
    async Task PrepareManualMerge(bool start){
      string reference=start?Ref():"";var existing=model.ContainsKey("manualMerge")?Data.Map(model["manualMerge"]):new Dictionary<string,object>();if(!start&&existing.ContainsKey("active")&&Convert.ToBoolean(existing["active"])&&!String.IsNullOrEmpty(Data.Text(existing,"parent"))){await Execute("open-cad-merge",new Dictionary<string,object>());return;}
      if(start&&reference=="refs/heads/"+Data.Text(model,"current"))throw new InvalidOperationException("请选择另一个需要合入的分支。");var data=Data.Map(await controller.Dispatch("merge-assemblies",new Dictionary<string,object>{{"reference",reference}},controller.Workspace()));if(!Alive)return;string preferred="";if(conflicts.SelectedItems.Count>0)preferred=Data.Text(Selected(conflicts),"path");else {string active=controller.ActivePath();if(active.StartsWith(workspace+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))preferred=active.Substring(workspace.Length+1).Replace('\\','/');}
      using(var dialog=new CadMergeSelectionDialog(data,preferred)){if(dialog.ShowDialog(this)!=DialogResult.OK)return;if(start)await Execute("merge-manual",new Dictionary<string,object>{{"reference",reference}});if(Alive)await Execute("prepare-cad-merge",dialog.Values);}
    }
    async Task ApplyManualResult(){
      string result=controller.ActivePath();using(var choose=new OpenFileDialog()){choose.Title="选择已经手工合图完成的最终总装";choose.Filter="SolidWorks 装配体|*.sldasm";choose.CheckFileExists=true;var manual=model.ContainsKey("manualMerge")?Data.Map(model["manualMerge"]):new Dictionary<string,object>();if(String.IsNullOrEmpty(result)||!result.EndsWith(".sldasm",StringComparison.OrdinalIgnoreCase))result=Data.Text(manual,"parent");if(!String.IsNullOrEmpty(result)){choose.FileName=result;choose.InitialDirectory=Path.GetDirectoryName(result);}if(choose.ShowDialog(this)!=DialogResult.OK)return;result=choose.FileName;}
      var plan=Data.Map(await controller.Dispatch("inspect-cad-result",new Dictionary<string,object>{{"result",result}},controller.Workspace()));if(!Alive)return;using(var dialog=new CadMergeResultDialog(plan)){if(dialog.ShowDialog(this)==DialogResult.OK)await Execute("apply-cad-result",dialog.Values);}
    }
    async Task MarkManualConflict(){string file=Data.Text(Selected(conflicts),"path");if(MessageBox.Show(this,"确认已经手工处理并保存该文件？\n"+file+"\n\n将保存当前图纸并暂存这个文件，标记对应冲突已解决。","gitpolar",MessageBoxButtons.YesNo,MessageBoxIcon.Question)==DialogResult.Yes)await Execute("mark-manual-resolved",new Dictionary<string,object>{{"path",file},{"confirmed",true}});}
    async Task AbortMerge(){if(MessageBox.Show(this,"中止本次合并，恢复合并前的工作区？","gitpolar",MessageBoxButtons.YesNo,MessageBoxIcon.Question)==DialogResult.Yes)await Execute("abort-merge",new Dictionary<string,object>());}
    async Task ReadLocks(){var data=Data.Map(await controller.Dispatch("locks",new Dictionary<string,object>(),controller.Workspace()));if(!Alive)return;var entries=new List<Dictionary<string,object>>();foreach(string key in new string[]{"ours","theirs"})foreach(var item in Data.Array(data,key).Select(Data.Map)){item["ownership"]=key=="ours"?"自己":"其他成员";entries.Add(item);}Fill(locks,entries,item=>new string[]{Data.Text(item,"path"),Data.Text(Data.Map(item["owner"]),"name"),Data.Text(item,"ownership")});}
    async Task ConfigureOrigin(){string url=Prompt("仓库连接","NAS 的 HTTP(S) 克隆地址（认证由 Git 凭据管理器处理）",Data.Text(model,"origin"));if(url!=null)await Execute("set-origin",new Dictionary<string,object>{{"url",url}});}
    string Prompt(string title,string caption,string initial){using(var form=new Form(){Width=620,Height=200,Text="gitpolar · "+title,StartPosition=FormStartPosition.CenterParent,FormBorderStyle=FormBorderStyle.FixedDialog,MinimizeBox=false,MaximizeBox=false}){Dark.Form(form);var label=Dark.Label(caption);label.SetBounds(12,14,570,30);var input=Dark.Input(initial);input.SetBounds(18,52,565,26);var save=Dark.Button("确定",(s,e)=>form.DialogResult=DialogResult.OK);save.SetBounds(482,103,100,31);form.Controls.AddRange(new Control[]{label,input,save});form.AcceptButton=save;return form.ShowDialog(this)==DialogResult.OK?input.Text.Trim():null;}}
    public async Task RunAction(string action,Dictionary<string,object> values){if(busy)throw new InvalidOperationException("分支窗口正在读取数据，请稍后再操作。");await RunUi(()=>Execute(action,values));}
    public void ShowManualMerge(){if(Alive)tabs.SelectedTab=manualTab;}
    public void SetStart(string commit){selectedCommit=commit??"";}
    public void ShowMessage(string message){if(Alive)status.Text=message;}
    public void RefreshState(){if(Alive)controller.StartUi(()=>RunUi(RefreshModel));}
    public string StateJson(){return new JavaScriptSerializer().Serialize(new {visible=Visible,loading=busy,error=lastError,current=Data.Text(model,"current"),branches=branches.Items.Count,stashes=stashes.Items.Count,tags=tags.Items.Count,conflicts=conflicts.Items.Count,manualMerge=model.ContainsKey("manualMerge")?model["manualMerge"]:null,selectedTab=tabs.SelectedTab==null?"":tabs.SelectedTab.Text,width=Width,height=Height});}
    public void SaveScreenshot(string file){using(var bitmap=new Bitmap(Width,Height)){DrawToBitmap(bitmap,new Rectangle(0,0,Width,Height));bitmap.Save(file,System.Drawing.Imaging.ImageFormat.Png);}}
  }
}
